head.script:
scwin.__checkErrLog = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf(String("org"));
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog() == -1", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
